#include <iostream>

class Thermostat {
public:
    explicit Thermostat(int initial) : target_(initial) {}
    void set_target(int value) { if (value >= 10 && value <= 30) target_ = value; }
    int target() const { return target_; }
private:
    int target_;
};
int main() {
    Thermostat thermostat{20}; thermostat.set_target(35);
    std::cout << thermostat.target() << '\n';
}
